#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const size_t MAX_INPUT = 1024; // limit on original string length
    if (argc <= 1) {
        /* No argument – treat as empty string */
        puts("PALINDROME");
        return 0;
    }

    const char *input = argv[1];
    size_t input_len = strlen(input);
    if (input_len > MAX_INPUT) {
        puts("TOO_LONG");
        return 0;
    }

    /* Build a normalized version: keep only alphanumeric characters,
       convert letters to lower case. */
    char norm[MAX_INPUT + 1];
    size_t norm_len = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[norm_len++] = (char)tolower(c);
        }
    }
    norm[norm_len] = '\0';

    /* Palindrome test on the normalized string */
    int is_pal = 1;
    for (size_t i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
